{
  "paper_title": "Validation of Modern JSON Schema: Formalization and Complexity",
  "research_problem": "To formally define the semantics of Modern JSON Schema (mJS), including its new features like dynamic references and annotation-dependent validation, and to analyze the computational complexity of the data validation process under this formal model.",
  "subgoals": [
    {
      "subgoal_id": "G1",
      "label": "Formalize the semantics of Modern JSON Schema",
      "description": "Develop a precise and unambiguous mathematical model of the validation semantics for Modern JSON Schema, covering new features like dynamic references and annotation-dependent validation that are subject to interpretation in the official specification.",
      "status": "achieved",
      "rationale": "The paper provides a formalization of mJS through a validation function, `validate(S, J, U)`, which was discussed with the JSON Schema tool developer community. This formal model serves as the basis for the subsequent complexity analysis."
    },
    {
      "subgoal_id": "G2",
      "label": "Determine the computational complexity of mJS validation",
      "description": "Establish the precise computational complexity class for validating a JSON instance against a Modern JSON Schema.",
      "status": "achieved",
      "rationale": "The paper proves that the data validation problem for mJS is PSPACE-complete. This is established through a reduction from the TQBF (True Quantified Boolean Formula) problem, as detailed in Section 5."
    },
    {
      "subgoal_id": "G3",
      "label": "Isolate the source of increased complexity",
      "description": "Identify which specific features of Modern JSON Schema (e.g., dynamic references, annotation-dependent validation) are responsible for the increase in computational complexity compared to previous versions.",
      "status": "achieved",
      "rationale": "The paper proves that the PSPACE-completeness arises from dynamic references introduced in Draft 2020-12, and not from annotation-dependent validation. It demonstrates that validation without dynamic references remains in the complexity class P."
    },
    {
      "subgoal_id": "G4",
      "label": "Differentiate between schema and data complexity",
      "description": "Analyze the validation complexity separately with respect to the size of the schema versus the size of the JSON data instance.",
      "status": "achieved",
      "rationale": "The analysis shows that validation is PSPACE-complete with respect to the schema size (even for a fixed data instance), but is polynomial (in P) when the schema is fixed and only the data instance size varies."
    },
    {
      "subgoal_id": "G5",
      "label": "Empirically demonstrate the theoretical complexity",
      "description": "Provide experimental evidence that the theoretical worst-case complexity can manifest in practice with realistic schemas and instances.",
      "status": "achieved",
      "rationale": "The paper presents experiments in Section 7 that show an exponential increase in validation runtime for a family of schemas that use nested dynamic references, confirming that the asymptotic complexity difference between dynamic and static references is observable in practice."
    },
    {
      "subgoal_id": "G6",
      "label": "Identify tractable fragments for practical validation",
      "description": "Characterize subsets of Modern JSON Schema or specific structural properties of schemas that guarantee more efficient (e.g., polynomial-time) validation, avoiding the general PSPACE-complete worst-case.",
      "status": "not_achieved",
      "rationale": "While the paper establishes the high worst-case complexity of mJS validation, it does not investigate or define any fragments of the language that would be computationally more tractable. The conclusion explicitly states that studying such properties is a direction for future work."
    }
  ]
}
```
